// src/lib/mcp/tools/get-offering.ts
var get_offering_default = defineTool({
  name: "get_offering",
  title: "Get offering details",
  description: "Get the full details of one Athena Revenue Partners offering by slug: overview, who it's for, process, deliverables and outcome.",
  inputSchema: {
    slug: z.string().trim().min(1).describe("Offering slug, e.g. 'revenue-diagnostic'."),
    audience: z.enum(["general", "private-equity"]).default("general").describe("Which catalogue the slug belongs to.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug, audience }) => {
    const found = audience === "private-equity" ? peOfferings.find((o) => o.slug === slug) : offerings.find((o) => o.slug === slug);
    if (!found) {
      const available = (audience === "private-equity" ? peOfferings : offerings).map((o) => o.slug).join(", ");
      throw new ToolError(`No offering with slug "${slug}". Available: ${available}`);
    }
    return {
      content: [{ type: "text", text: JSON.stringify(found, null, 2) }],
      structuredContent: { offering: found }
    };
  }
});

// src/lib/mcp/tools/list-offerings.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@2.2.1";
import { z as z2 } from "npm:zod@^3.25.76";
var audienceSchema = z2.enum(["all", "general", "private-equity"]);
var list_offerings_default = defineTool2({
  name: "list_offerings",
  title: "List offerings",
  description: "List Athena Revenue Partners' consulting offerings with slug, name, duration and a short summary. Optionally filter by audience.",
  inputSchema: {
    audience: audienceSchema.default("all").describe("Which catalogue to list: 'general', 'private-equity', or 'all'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ audience }) => {
    const general = offerings.map((o) => ({
      audience: "general",
      slug: o.slug,
      name: o.name,
      duration: o.duration,
      summary: o.summary,
      investment: o.investment
    }));
    const pe = peOfferings.map((o) => ({
      audience: "private-equity",
      slug: o.slug,
      name: o.name,
      stage: o.tag,
      summary: o.summary
    }));
    const items = audience === "general" ? general : audience === "private-equity" ? pe : [...general, ...pe];
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { items }
    };
  }
});

