// src/lib/mcp/tools/request-diagnostic.ts
var request_diagnostic_default = defineTool3({
  name: "request_diagnostic",
  title: "Request a revenue diagnostic",
  description: "Submit a diagnostic request to Athena Revenue Partners \u2014 the same enquiry the website's 'Book a diagnostic' form sends. Only submit with the person's explicit consent and their real contact details.",
  inputSchema: {
    name: z3.string().trim().min(1).max(100).describe("Full name of the person requesting."),
    email: z3.string().trim().email().max(255).describe("Business email address."),
    company: z3.string().trim().max(150).optional().describe("Company name."),
    role: z3.string().trim().max(100).optional().describe("Job title, e.g. CEO or CRO."),
    arr_stage: z3.string().trim().max(100).optional().describe("Current ARR or funding stage."),
    challenge: z3.string().trim().max(1e3).optional().describe("The revenue challenge they want help with.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
  handler: async ({ name, email, company, role, arr_stage, challenge }) => {
    const supabase = supabaseAnon();
    const { error } = await supabase.from("diagnostic_requests").insert({
      id: crypto.randomUUID(),
      name,
      email,
      company: company || null,
      role: role || null,
      arr_stage: arr_stage || null,
      challenge: challenge || null
    });
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    return {
      content: [
        {
          type: "text",
          text: `Diagnostic request submitted for ${name} (${email}). The Athena team will follow up by email.`
        }
      ]
    };
  }
});

